from pathlib import Path
import hashlib,json,os,shutil,sys,time
out=Path(__file__).resolve().parent;p=json.loads((out/'plan.json').read_text());root=Path(p['root'])
sys.path.insert(0,str(root/'tools'));import native_process
begin=time.monotonic();records=[];pids=[];result={'passed':False}
Base=native_process._PosixTree
class ObservedTree(Base):
 def __init__(self,*a,**k):
  super().__init__(*a,**k);pids.append(self.process.pid)
native_process._PosixTree=ObservedTree
binary=Path(p['binary']);assert hashlib.sha256(binary.read_bytes()).hexdigest()==p['binary_sha256']
def check():
 if time.monotonic()-begin>p['stage_limit_seconds']:raise TimeoutError('overall fixture qualification deadline')
 if shutil.disk_usage(out).free<p['minimum_free_bytes']:raise RuntimeError('free space floor')
 files=[v for v in out.rglob('*') if v.is_file()]
 if sum(v.stat().st_size for v in files)>p['output_limit_bytes']:raise RuntimeError('output bound')
 if sum(v.stat().st_size for v in files if v.suffix=='.log')>p['log_limit_bytes']:raise RuntimeError('log bound')
def run(*args):
 check();i=len(records);cmd=[str(binary),*map(str,args)];row={'argv':cmd};records.append(row)
 with (out/f'{i}.out.log').open('wb') as stdout,(out/f'{i}.err.log').open('wb') as stderr:
  r=native_process.run(cmd,cwd=root,timeout=p['child_limit_seconds'],stdout=stdout,stderr=stderr,cancel=check)
 row.update(exit=r.returncode,pid=pids[-1],managed_cleanup_returned=True)
 assert r.returncode==0,(cmd,r.returncode,(out/f'{i}.err.log').read_text())
 return json.loads((out/f'{i}.out.log').read_text())
try:
 project=out/'project.json';run('init',project,'--entities','0')
 (out/'refresh.gltf').write_bytes((out/'original.gltf').read_bytes());a=run('import',project,'refresh.gltf')
 (out/'refresh.gltf').write_bytes((out/'replacement.gltf').read_bytes());b=run('import',project,'refresh.gltf')
 c=run('import',project,'refresh.gltf');v=run('validate',project)
 (out/'import-responses.json').write_text(json.dumps([a,b,c,v],indent=2)+'\n')
 result.update(passed=True,actual_imports=3,validated=v,window=False,claim='Fixture import only; no live refresh, pixels or performance claim')
except BaseException as error:
 result['error']=repr(error);raise
finally:
 absence=[]
 for pid in pids:
  row={'pid':pid}
  for name,fn in [('pid_absent',os.kill),('group_absent',os.killpg)]:
   try:fn(pid,0);row[name]=False
   except ProcessLookupError:row[name]=True
   except OSError as e:row[name]=False;row[name+'_error']=repr(e)
  absence.append(row)
 result.update(seconds=time.monotonic()-begin,processes=records,absence=absence,output_bytes=sum(v.stat().st_size for v in out.rglob('*') if v.is_file()))
 (out/'result.json').write_text(json.dumps(result,indent=2)+'\n')
 assert all(r['pid_absent'] and r['group_absent'] for r in absence),'owned processes remain'
print(json.dumps({'passed':result['passed'],'output':str(out),'seconds':result['seconds']}))

